#[test]
fn staged_symlink_is_refused_as_an_unsupported_mode() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    init_repo(root);
    commit_file(root, "a.txt", b"seed\n", "feat: seed");
    let base = head(root);
    std::os::unix::fs::symlink("a.txt", root.join("link")).unwrap();
    git(root, &["add", "link"]);

    assert!(matches!(
        commit_plan_error(root, &base),
        Some(ReleasePrDecisionError::UnsupportedFileMode { ref path, mode: 0o120000 }) if path == "link"
    ));
}

