    std::os::unix::fs::symlink("a.txt", root.join("link")).unwrap();
    git(root, &["add", "link"]);

    assert!(matches!(
        commit_plan_error(root, &base),
        Some(ReleasePrDecisionError::UnsupportedFileMode { ref path, mode: 0o120000 }) if path == "link"
    ));
}

#[test]
fn staged_submodule_is_refused_as_an_unsupported_mode() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    init_repo(root);
    commit_file(root, "a.txt", b"seed\n", "feat: seed");
    let base = head(root);
    let cacheinfo = format!("160000,{},sub", base.as_str());
    git(root, &["update-index", "--add", "--cacheinfo", &cacheinfo]);

    assert!(matches!(
        commit_plan_error(root, &base),
        Some(ReleasePrDecisionError::UnsupportedFileMode { ref path, mode: 0o160000 }) if path == "sub"
    ));
}

/// With `core.autocrlf`, the staged blob has LF endings while the worktree file has CRLF; the emitted
/// worktree bytes would differ from what is staged, so the read must fail.
#[test]
fn staged_changes_since_rejects_worktree_bytes_that_a_clean_filter_changed() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    init_repo(root);
    commit_file(root, "a.txt", b"seed\n", "feat: seed");
    let base = head(root);
    git(root, &["config", "core.autocrlf", "true"]);
    std::fs::write(root.join("crlf.txt"), b"one\r\ntwo\r\n").unwrap();
    git(root, &["add", "crlf.txt"]);

    let result = GitAccess::new(root, &SystemGit).staged_changes_since(&base);

    assert!(
        matches!(result, Err(VcsError::StagedContentMismatch { ref path, .. }) if path == "crlf.txt"),
        "got {result:?}"
    );
}

